import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.D7EuCHIT.js";const h=JSON.parse('{"title":"SDK 版本与兼容性","description":"","frontmatter":{},"headers":[],"relativePath":"reference/snapshot.md","filePath":"reference/snapshot.md","lastUpdated":1791890216000}'),s={name:"reference/snapshot.md"};function n(d,e,i,c,p,l){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="sdk-版本与兼容性" tabindex="-1">SDK 版本与兼容性 <a class="header-anchor" href="#sdk-版本与兼容性" aria-label="Permalink to &quot;SDK 版本与兼容性&quot;">​</a></h1><p>公开插件契约预览：SDK ABI <strong>3</strong>，接口版本 <strong>3</strong>，文档版本 <strong>0.3.3</strong>。对应基准宿主版本 <code>62adff0</code>，更高版本需以运行时能力查询为准。页面不承诺所有安装包都支持全部可选能力。</p><p>Lyra Player 为闭源软件。开发插件只需要公开 SDK、NDK 和安装好的宿主，不需要播放器源码、主程序构建链或签名凭据。</p><p><a href="/LyraPlayer-docs-site/downloads/lyra-plugin-sdk.zip">SDK 与示例下载</a> · <a href="/LyraPlayer-docs-site/downloads/manifest.json">公开文件摘要</a> · <a href="/LyraPlayer-docs-site/config/reference/">全部配置</a>。摘要用于版本一致性，不是签名发布证明。</p><h2 id="兼容规则" tabindex="-1">兼容规则 <a class="header-anchor" href="#兼容规则" aria-label="Permalink to &quot;兼容规则&quot;">​</a></h2><p>当前内测只接受 ABI 3。Host、插件和接口均须使用当前完整布局，size 填写 sizeof；不读取旧结构前缀、不适配旧查询或旧播放命令，也不迁移旧配置键。不同 ABI 的插件必须重新编译。先 query_interface，再检查当前 version、size 和可选回调。</p><p>Android arm64-v8a 插件不能作为 PC 插件直接加载。非 Android 宿主的 VM/Activity 可为空；目前不提供可下载的 PC 宿主。</p><h2 id="文档维护" tabindex="-1">文档维护 <a class="header-anchor" href="#文档维护" aria-label="Permalink to &quot;文档维护&quot;">​</a></h2><p>参考内容从仓库内审核后的公开 <code>reference-data</code> 和 SDK 生成，脚本不读取播放器源码。更新公开契约后运行 <code>npm run sync</code>、<code>npm run build</code>。语义变化还需人工审查教程。</p>',9)])])}const _=a(s,[["render",n]]);export{h as __pageData,_ as default};
